import pandas as pd
import numpy as np

# Load the data
crime_data = pd.read_csv('chunks_csv/moran_local_no2crime_crime_first_half_2016.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Replace the missing value in the crime data with the mean of the non-missing values
crime_data['value'] = crime_data['value'].fillna(crime_data['value'].mean())

# Compute neighborhood averages
neighborhood_averages = {}
for index, row in adjacency_data.iterrows():
    borough = row['borough']
    neighbors = adjacency_data.loc[adjacency_data['neighbor'] == borough, 'borough'].tolist()
    neighborhood_averages[borough] = crime_data.loc[crime_data['borough'].isin(neighbors), 'value'].mean()

# Compute local Moran's I
local_morans_i = {}
for index, row in crime_data.iterrows():
    borough = row['borough']
    neighbors = adjacency_data.loc[adjacency_data['neighbor'] == borough, 'borough'].tolist()
    local_morans_i[borough] = np.corrcoef(crime_data.loc[crime_data['borough'] == borough, 'value'], crime_data.loc[crime_data['borough'].isin(neighbors), 'value'])[0, 1]

# Determine hot and cold spots
hot_spots = []
cold_spots = []
for borough, value in local_morans_i.items():
    if crime_data.loc[crime_data['borough'] == borough, 'value'].mean() > 350 and np.mean([neighborhood_averages[n] for n in adjacency_data.loc[adjacency_data['neighbor'] == borough, 'borough'].tolist()]) > 350:
        hot_spots.append((borough, value))
    elif crime_data.loc[crime_data['borough'] == borough, 'value'].mean() < 100 and np.mean([neighborhood_averages[n] for n in adjacency_data.loc[adjacency_data['neighbor'] == borough, 'borough'].tolist()]) < 100:
        cold_spots.append((borough, value))

# Perform permutation test
def permutation_test(borough, value):
    crime_data_copy = crime_data.copy()
    crime_data_copy['value'] = crime_data_copy['value'].sample(frac=1)
    neighborhood_averages_copy = {}
    for index, row in adjacency_data.iterrows():
        borough = row['borough']
        neighbors = adjacency_data.loc[adjacency_data['neighbor'] == borough, 'borough'].tolist()
        neighborhood_averages_copy[borough] = crime_data_copy.loc[crime_data_copy['borough'].isin(neighbors), 'value'].mean()
    local_morans_i_copy = {}
    for index, row in crime_data_copy.iterrows():
        borough = row['borough']
        neighbors = adjacency_data.loc[adjacency_data['neighbor'] == borough, 'borough'].tolist()
        local_morans_i_copy[borough] = np.corrcoef(crime_data_copy.loc[crime_data_copy['borough'] == borough, 'value'], crime_data_copy.loc[crime_data_copy['borough'].isin(neighbors), 'value'])[0, 1]
    p_value = 0
    for _ in range(500):
        p_value += local_morans_i_copy[borough] > value
    return p_value / 500

for borough, value in hot_spots + cold_spots:
    print(f"Permutation test p-value for {borough}: {permutation_test(borough, value)}")

# Report results
data_points_used = len(crime_data)
print(f"data_points_used = {data_points_used}")
if hot_spots:
    print(f"FINAL ANSWER: {', '.join([f'{borough} (HH, local Moran\'s I = {value})' for borough, value in hot_spots])}")
elif cold_spots:
    print(f"FINAL ANSWER: {', '.join([f'{borough} (LL, local Moran\'s I = {value})' for borough, value in cold_spots])}")
else:
    print("FINAL ANSWER: none")
